const searchRequest = {
  model: 'gpt-5-mini',
  reasoning: { effort: 'low' },
  tools: [
    {
      type: 'web_search',
      filters: {
        allowed_domains: [
          'reuters.com',
          'www.reuters.com',
          'cna.com',
          'www.cna.com',
          'channelnewsasia.com',
          'www.channelnewsasia.com',
          'straitstimes.com',
          'www.straitstimes.com'
        ]
      }
    }
  ],
  tool_choice: 'auto',
  text: {
    format: {
      type: 'json_schema',
      name: 'sharedspace_live_source_search',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          search_summary: { type: 'string' },
          matched_sources: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                name: { type: 'string' },
                tier: { type: 'integer' },
                title: { type: 'string' },
                url: { type: 'string' },
                snippet: { type: 'string' },
                match_type: { type: 'string' },
                relevance_note: { type: 'string' }
              },
              required: ['name', 'tier', 'title', 'url', 'snippet', 'match_type', 'relevance_note']
            }
          }
        },
        required: ['search_summary', 'matched_sources']
      }
    }
  },
  input: [
    {
      role: 'system',
      content: 'Return JSON only. Search Reuters, CNA, and The Straits Times for live source evidence matching the user draft. Do not score the article in this step.'
    },
    {
      role: 'user',
      content: $json.search_prompt
    }
  ]
};

return [{ json: { ...$json, search_request: searchRequest } }];

const raw = $json.output_text || $json.output?.find((item) => item.type === 'message')?.content?.find((part) => part.type === 'output_text')?.text || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = { search_summary: 'Search response could not be parsed.', matched_sources: [] };
}

const upstream = $items('Build Search Request', 0, 0)?.json || {};
const allowedNames = ['Reuters', 'CNA', 'The Straits Times'];
const normalizeName = (name, url) => {
  const value = String(name || '').toLowerCase();
  const link = String(url || '').toLowerCase();
  if (value.includes('reuters') || link.includes('reuters.com')) return 'Reuters';
  if (value.includes('cna') || value.includes('channel newsasia') || link.includes('cna.com') || link.includes('channelnewsasia.com')) return 'CNA';
  if (value.includes('straits') || link.includes('straitstimes.com')) return 'The Straits Times';
  return String(name || 'Unknown');
};

const matchedSources = Array.isArray(parsed.matched_sources)
  ? parsed.matched_sources.slice(0, 5).map((source) => {
      const name = normalizeName(source.name, source.url);
      return {
        name,
        tier: allowedNames.includes(name) ? 1 : Number(source.tier || 2),
        title: String(source.title || ''),
        url: String(source.url || ''),
        snippet: String(source.snippet || ''),
        match_type: String(source.match_type || 'related').toLowerCase(),
        relevance_note: String(source.relevance_note || '')
      };
    }).filter((source) => source.title || source.url || source.snippet)
  : [];

return [{
  json: {
    ...upstream,
    search_summary: String(parsed.search_summary || ''),
    matched_sources: matchedSources,
    matched_articles: matchedSources.map((source) => ({
      title: source.title,
      url: source.url,
      relevance_note: source.relevance_note
    }))
  }
}];

const raw = $json.output_text || $json.output?.find((item) => item.type === 'message')?.content?.find((part) => part.type === 'output_text')?.text || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
const upstream = $items('Build Compare Request', 0, 0)?.json || {};

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  return [{
    json: {
      trust_score: 0,
      summary: 'AI returned invalid JSON.',
      verdict: 'Verification failed. Check the comparison response in n8n.',
      metrics: {
        factual_accuracy: 0,
        source_quality: 0,
        bias_detection: 0,
        logical_consistency: 0,
        completeness: 0
      },
      source_label: 'Invalid AI response',
      matched_articles: upstream.matched_articles || []
    }
  }];
}

const clamp = (value, max) => Math.max(0, Math.min(max, parseInt(value ?? 0, 10) || 0));
const categories = parsed.categories || {};
const factual = clamp(categories.factual_accuracy?.score, 35);
const source = clamp(categories.source_quality?.score, 20);
const bias = clamp(categories.bias_neutrality?.score, 20);
const logical = clamp(categories.logical_consistency?.score, 15);
const completeness = clamp(categories.completeness?.score, 10);

let trust = factual + source + bias + logical + completeness;
let decision = String(parsed.publish_decision || '').trim();
let overrideApplied = Boolean(parsed.override_applied);
let overrideReason = parsed.override_reason ? String(parsed.override_reason) : null;

const hasHeadlineContradiction = (parsed.matched_sources || upstream.matched_sources || []).some((source) => String(source.match_type || '').toLowerCase() === 'contradicts');
if (hasHeadlineContradiction) {
  overrideApplied = true;
  overrideReason = overrideReason || 'A Tier 1 source directly contradicts the article headline or core claim.';
}
if (source === 0 && factual <= 10) {
  overrideApplied = true;
  overrideReason = overrideReason || 'No reliable source match and factual accuracy is too low.';
}

if (overrideApplied || trust < 50 || factual < 15 || source === 0) {
  decision = 'not_reliable';
} else if (trust >= 75 && factual >= 25 && bias >= 13) {
  decision = 'safe_to_publish';
} else {
  decision = 'needs_review';
}

const verdictMap = {
  safe_to_publish: 'Safe to publish. The article is supported by reliable sources and meets the rubric threshold.',
  needs_review: 'Needs review. The article has some support but should be improved before publishing.',
  not_reliable: 'Not reliable. The article does not meet the minimum verification threshold.'
};

const notes = [
  categories.factual_accuracy?.notes,
  categories.source_quality?.notes,
  categories.bias_neutrality?.notes,
  categories.logical_consistency?.notes,
  categories.completeness?.notes
].filter(Boolean).join(' ');

const matchedSources = Array.isArray(parsed.matched_sources) && parsed.matched_sources.length
  ? parsed.matched_sources
  : (upstream.matched_sources || []);

return [{
  json: {
    trust_score: trust,
    summary: notes || 'Verification completed using the SharedSpace scoring rubric.',
    verdict: overrideReason ? `${verdictMap[decision]} ${overrideReason}` : verdictMap[decision],
    publish_decision: decision,
    metrics: {
      factual_accuracy: Math.round((factual / 35) * 100),
      source_quality: Math.round((source / 20) * 100),
      bias_detection: Math.round((bias / 20) * 100),
      logical_consistency: Math.round((logical / 15) * 100),
      completeness: Math.round((completeness / 10) * 100)
    },
    rubric_scores: {
      factual_accuracy: factual,
      source_quality: source,
      bias_neutrality: bias,
      logical_consistency: logical,
      completeness
    },
    source_label: matchedSources.length
      ? `Compared against ${matchedSources.length} trusted source${matchedSources.length === 1 ? '' : 's'}.`
      : 'No trusted source match found.',
    matched_sources: matchedSources,
    matched_articles: matchedSources.map((source) => ({
      title: source.title || source.name || '',
      url: source.url || '',
      relevance_note: source.relevance_note || source.match_type || ''
    })),
    flags: parsed.flags || [],
    override_applied: overrideApplied,
    override_reason: overrideReason
  }
}];
